INSERT INTO `tb_shop` (`id`,`merchant_id`,`name`,`code`,`province`,`city`,`area`,`street`,`is_operating`,`start_time`,`end_time`,`manage_primary`,`manage_minor`,`shop_img`,`shop_within_img`,`shop_logo_img`,`certificate_type1`,`certificate_img1`,`certificate_type2`,`certificate_img2`,`special_type`,`special_img`,`audit_status`,`audit_reason`,`audit_time`,`take_out_phone`,`contact_realname`,`contact_phone`,`announcement`,`brief_introduction`,`start_delivery_price`,`delivery_starting_price`,`delivery_kilometer_price`,`delivery_distance_limit`,`service_rating`,`business_license`,`id_card_front_side`,`id_card_back_side`,`status`,`reduced_delivery_price`,`is_open_order_audio`,`is_open_local_print`,`is_open_cloud_print`,`first_poster`,`house_number`,`longitude`,`latitude`,`checkout_mode`,`create_time`,`update_time`,`kitchen_total_order_printer_id`,`checkout_printer_id`) VALUES (15,20,'小气茶（奥林匹克店）','','湖南','长沙','岳麓区','长沙市岳麓区潇湘奥林匹克花园',1,'0:00','23:59','奶茶/糕点','','','data/images/merchant/20/deerspot_1602063036566.jpg','data/images/merchant/20/deerspot_1600788526211.jpg','','','','','','',2,'','2020-09-22 22:21:12','','暹罗','13121865386','营业时间：10:00-22:00，新推出爆款老虎班茶，如有疑问，请来电咨询哟17378131291','“小气茶”自创立开始，始终坚持口感至上，旨在用匠心为您还原一杯好茶，以奶霜茶与水果茶为主打，通过新颖的萃取方式，打造一杯“知心”茶饮，为您的生活重新定义。在这里，我们不仅是一杯奶茶，更是一种全新的生活方式，捧上一杯符合自己心情的“小气茶”，让您“饮在此，乐在此” ！','20.00','0.00','0.00','0.00','0.0','','','',2,'0.00',0,1,0,'data/images/merchant/20/deerspot_1600789239415.jpg','13、15栋-140号','112.876846','28.236901',1,'2020-09-22 22:11:51','2021-07-01 18:39:26',NULL,NULL);
INSERT INTO `tb_shop` (`id`,`merchant_id`,`name`,`code`,`province`,`city`,`area`,`street`,`is_operating`,`start_time`,`end_time`,`manage_primary`,`manage_minor`,`shop_img`,`shop_within_img`,`shop_logo_img`,`certificate_type1`,`certificate_img1`,`certificate_type2`,`certificate_img2`,`special_type`,`special_img`,`audit_status`,`audit_reason`,`audit_time`,`take_out_phone`,`contact_realname`,`contact_phone`,`announcement`,`brief_introduction`,`start_delivery_price`,`delivery_starting_price`,`delivery_kilometer_price`,`delivery_distance_limit`,`service_rating`,`business_license`,`id_card_front_side`,`id_card_back_side`,`status`,`reduced_delivery_price`,`is_open_order_audio`,`is_open_local_print`,`is_open_cloud_print`,`first_poster`,`house_number`,`longitude`,`latitude`,`checkout_mode`,`create_time`,`update_time`,`kitchen_total_order_printer_id`,`checkout_printer_id`) VALUES (16,21,'满杯烧仙草（尖山小区店）','','湖南','长沙','岳麓区','长沙市岳麓区尖山安置小区',1,'0:00','23:59','奶茶','','','data/images/merchant/21/deerspot_1602146334499.jpg,data/images/merchant/21/deerspot_1602146349974.jpg','data/images/merchant/21/deerspot_1602146134395.jpg','','','','','','',2,'','2020-10-08 16:24:28','','暹罗','13121865386','营业时间：10:00-23:59,本店爆款-白桃乌龙拿铁，如在用餐过程中遇到任何问题，请致电13723860098咨询','满杯烧仙草相信很多朋友都十分的熟悉，这是一个有着十多年历史的老品牌，一直以满杯用料著称的“满杯烧仙草”如今更是不断升级，料更扎实，口感更出众。满满一杯的仙草冻、蜜红豆、珍珠、椰果、花生碎和葡萄干，让消费者吃个过瘾。一根吸管搭配一个勺子，随便舀一勺都是料，喝光后再用勺子把底料收进胃囊，瞬间让人一种满满的幸福感。对于品质的要求是十分严格的。每天早上先将仙草汁熬上两个小时，再常温凝固成仙草冻，点单时才将其捣碎，每一块都细腻嫩滑。丰富的配料，现打奶盖等，都可以任意添加，更好的满足了消费者的不同口味。','20.00','0.00','0.00','0.00','0.0','','','',2,'0.00',1,0,0,'data/images/merchant/21/deerspot_1602159577496.jpg','26栋3号','112.890548','28.257409',1,'2020-10-08 16:19:37','2021-07-01 18:39:24',NULL,NULL);
